SELECT COUNT(DISTINCT customer_unique_id) AS customers
FROM customers
WHERE customer_state = 'BA';

SELECT COUNT(*) AS products_with_5_or_more_photos
FROM products
WHERE product_photos_qty >= 5;

SELECT ROUND(AVG((julianday(order_approved_at) - julianday(order_purchase_timestamp)) * 24), 2) AS avg_hours
FROM orders
WHERE order_approved_at IS NOT NULL;
